    {
      "Effect": "Allow",
      "Principal": {
        "Federated": "arn:aws:iam::123456789098:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/20C159CDF6F2349B68846BEC03BE031B"
      },
      "Action": "sts:AssumeRoleWithWebIdentity",
